import {play,stop} from './audio.js';
import {searchReferences} from './search.js';
import {createProgressStore,PROGRESS_KEY} from './progress.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={theory:'Music theory for producers',strudel:'Making music with Strudel'};let courses={},all=[],reference=[],glossary={},track='theory',step=0,passed=new Set(),completed=new Set(),save=false,progressStore=null,ready=false,importRequest=0;
const referenceState={q:'',category:'',limit:30};let glossaryQuery='';
function syncProgress(state,message='',ok=true){passed=state.passed;completed=state.completed;save=state.enabled;$('#saveProgress').checked=save;$('#storageMessage').textContent=message;$('#progressAlert').hidden=ok;$('#progressAlert').textContent=ok?'':message;if(courses[track]){const list=courses[track];const meta=$('#courseMeta .course-small');if(meta)meta.textContent=`${list.length} small lessons · ${list.filter(l=>completed.has(l.id)).length} reflected on`;document.querySelectorAll('#lessonNav .lesson-link').forEach(a=>{const key=a.getAttribute('href').slice(8);a.classList.toggle('done',completed.has(key));const n=a.querySelector('.lesson-no');if(n)n.textContent=completed.has(key)?'✓':String(list.findIndex(l=>l.id===key)+1)})}const id=location.hash.startsWith('#lesson/')?location.hash.slice(8):null;if($('#markDone')&&id){$('#markDone').disabled=!passed.has(id);$('#markDone').textContent=completed.has(id)?'✓ Reflected on':'Mark reflected on'}}
const genreMeta=[['dubstep','Dubstep','Heavy bass music','Set up a drop, leave room for bass dialogue, then make the return matter.'],['trance','Trance','Electronic · dance','Connect a steady engine with melodic anticipation, release and a purposeful outro.'],['synthwave','Synthwave','Electronic · melodic','Build a driving pulse, clear harmonic colors and a memorable melodic foreground.'],['rap','Rap','Voice-led song','Protect the verse pocket, give the hook a job and vary the backing around the voice.'],['pop','Pop','Song form','Make verse, prechorus, chorus and bridge serve different musical purposes.'],['classical','Classical forms','Selected instrumental forms','Explore phrases, binary, ternary, rondo, sonata functions and variations—not every classical form.'],['cinematic','Cinematic cues','Music for narrative','Shape entry, pressure, arrival and exit around a scene—not a standardized song layout.']];
function nav(){ $('.topbar>a.quiet').href='#map/'+track;$('#courseSelect').value=track;const list=courses[track];$('#unitSelect').innerHTML='<option value="">Jump to a topic…</option>'+[...new Set(list.map(l=>l.unit))].map(u=>`<option value="${esc(u)}">${esc(u)}</option>`).join('');$('#courseMeta').innerHTML=`<p class="course-small">${list.length} small lessons · ${list.filter(l=>completed.has(l.id)).length} reflected on</p>`;let unit='';$('#lessonNav').innerHTML=list.map((l,i)=>{let h='';if(unit!==l.unit){unit=l.unit;h=`<div class="module-label">${esc(unit)}</div>`}return h+`<a class="lesson-link ${location.hash==='#lesson/'+l.id?'active':''} ${completed.has(l.id)?'done':''}" href="#lesson/${esc(l.id)}"><span class="lesson-no">${completed.has(l.id)?'✓':i+1}</span><span>${esc(l.title)}</span></a>`}).join('');document.querySelectorAll('[data-track]').forEach(a=>{const active=a.dataset.track===(location.hash.startsWith('#reference')?'reference':location.hash.startsWith('#genre')||all.find(l=>'#lesson/'+l.id===location.hash)?.genre?'genres':track);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}
function home(){ $('#main').innerHTML=`<section class="hero"><div class="eyebrow">LISTEN. UNDERSTAND. MAKE IT YOURS.</div><h1>Small ideas.<br>More musical possibilities.</h1><p>Start from zero. Build the understanding to make deliberate choices—in your DAW and in Strudel.</p></section><div class="coursecards">${Object.entries(titles).map(([t,title],i)=>`<section class="coursecard"><div class="map-top"><span class="pill">${i?'PATTERNS & CODE':'SOUND & STRUCTURE'}</span><span class="course-number">0${i+1}</span></div><h2>${title}</h2><p>${i?'Read a pattern, predict what it does, then try an original change in external Strudel. No coding background needed.':'Hear rhythm, understand notes and chords, and shape musical ideas. Connect theory to production without confusing it with mixing.'}</p><p class="small">${courses[t].length} lessons · clear examples · understanding checks</p><a class="link-button primary" href="#lesson/${courses[t][0].id}">Start with the first idea →</a><a style="margin-left:16px" href="#map/${t}">Explore the path</a></section>`).join('')}</div><section class="genre-banner"><div><div class="eyebrow">APPLIED MUSIC THEORY</div><h2>Build a section with purpose.</h2><p>Seven distinct genre workshops. Learn what each section does, why sounds can complement one another, and how to try the idea in your DAW.</p></div><a class="link-button primary" href="#genres">Explore genre arrangements →</a></section><div class="notice">These are bounded learning paths, not a guarantee of professional results. Advanced work grows through listening, experimentation, and making many original pieces. Go at your pace; there are no locked lessons or streaks.</div><div class="secondary-nav"><a href="#reference">Search the Strudel function guide →</a><a href="#glossary">Untangle a new word →</a><a href="#about">Scope, sources & sound safety →</a></div>`}
function map(unitFilter=''){if(unitFilter&&!courses[track].some(l=>l.unit===unitFilter)){notFound('That topic is not available.');return}const list=courses[track].filter(l=>!unitFilter||l.unit===unitFilter),units=[...new Set(list.map(l=>l.unit))];$('#main').innerHTML=`<div class="eyebrow">YOUR COURSE MAP</div><h1>${esc(unitFilter||titles[track])}</h1><p class="map-intro">Follow the sequence, or revisit an idea. Each lesson names its prerequisites. A check tests the idea; a small transfer task puts it to work.</p><div class="coursecards">${units.map((u,i)=>`<section class="coursecard"><div class="map-top"><span class="pill">${esc(list.find(l=>l.unit===u).level)}</span><span class="course-number">${String(i+1).padStart(2,'0')}</span></div><h2>${esc(u)}</h2><ul class="unit-lessons">${list.filter(l=>l.unit===u).map(l=>`<li><a href="#lesson/${l.id}">${completed.has(l.id)?'✓ ':''}${esc(l.title)}</a></li>`).join('')}</ul></section>`).join('')}</div>`}
function genres(slug=''){const meta=genreMeta.find(g=>g[0]===slug);if(slug&&meta){const lessons=courses.theory.filter(l=>l.genre===slug);$('#main').innerHTML=`<div class="breadcrumb"><a href="#genres">Genre arrangement studio</a><span>/</span>${esc(meta[1])}</div><span class="pill">${esc(meta[2])}</span><h1>${esc(meta[1])}</h1><p class="map-intro">${esc(meta[3])}</p><div class="notice">Original studies, not fixed rules or artist recreations. Each lesson focuses on one section job and a concrete sound-pairing decision. Review its named prerequisites before the external DAW task.</div><div class="coursecards">${lessons.map((l,i)=>`<section class="coursecard"><span class="course-number">${String(i+1).padStart(2,'0')}</span><h2>${esc(l.title)}</h2><p>${esc(l.goal)}</p><a href="#lesson/${l.id}">${completed.has(l.id)?'✓ Revisit':'Open'} this idea →</a></section>`).join('')}</div><div class="secondary-nav"><a href="#genres">← All genre topics</a><a href="#map/theory">Full music-theory map →</a></div>`;return}const foundation=courses.theory.filter(l=>l.genre==='bridge');$('#main').innerHTML=`<div class="eyebrow">ARRANGEMENT IS MUSICAL DECISION-MAKING</div><h1>What should this section do?</h1><p class="map-intro">Work from a purpose, not a preset list. Compare how rhythm, harmony, bass, timbre, register and space support the result you want.</p><section class="genre-banner"><div><h2>Start with two useful questions.</h2><p>What is the section’s job? Which sounds support that job without competing?</p><div class="lesson-links">${foundation.map(l=>`<a href="#lesson/${l.id}">${esc(l.title)} →</a>`).join('')}</div></div></section><p class="course-scope-note">Related electronic styles sit together below, followed by voice-led songs, selected classical forms and narrative cues. These are separate topics, not a ranking or a claim that genres have rigid boundaries.</p><div class="coursecards">${genreMeta.map((g,i)=>`<section class="coursecard"><div class="map-top"><span class="pill">${esc(g[2])}</span><span class="course-number">${String(i+1).padStart(2,'0')}</span></div><h2>${esc(g[1])}</h2><p>${esc(g[3])}</p><p class="small">${courses.theory.filter(l=>l.genre===g[0]).length} section-by-section lessons</p><a href="#genre/${g[0]}">Explore ${esc(g[1])} →</a></section>`).join('')}</div><div class="notice">The examples are independently composed sketches. Heavy-bass artist interests can guide your listening, but this studio does not teach copied songs or claim a fixed recipe for Zeds Dead, Subtronics, Excision, Sullivan King or Eptic.</div>`}
function sectionDiagram(ex){if(ex.sectionPlan)return `<section class="section-diagram" aria-label="Illustrative section plan"><div class="smallheading">ONE ORIGINAL SECTION PLAN</div><div class="section-blocks">${ex.sectionPlan.map(p=>`<div class="section-block ${p.active?'focus-section':''}">${p.active?'<span class="tag">Lesson focus</span>':''}<strong>${esc(p.label)}</strong><span>${esc(p.bars)} bars</span><p>${esc(p.role)}</p></div>`).join('')}</div><p class="caption">${ex.planScope?esc(ex.planScope)+' ':''}Fixed planning example, not a required genre formula. Boxes show order, not proportional duration; bar lengths are labeled. This is not an editor or a moving playhead.</p></section>`;if(ex.cuePlan)return `<section class="section-diagram" aria-label="Illustrative narrative cue plan"><div class="smallheading">A HYPOTHETICAL SCENE</div><div class="section-blocks">${ex.cuePlan.map(p=>`<div class="section-block"><strong>${esc(p.label)}</strong><span>${esc(p.time)}</span><p>${esc(p.role)}</p></div>`).join('')}</div><p class="caption">Fixed story plan with selected time points—not a standard cinematic song structure or a playable film.</p></section>`;return ''}
const noteName=m=>['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][((m%12)+12)%12]+(Math.floor(m/12)-1);
function example(l){const ex=l.example;return `<section class="visual-card"><div class="visual-label">A WORKED EXAMPLE <span>Original</span></div><h3>${esc(ex.title)}</h3><p>${esc(ex.text)}</p>${sectionDiagram(ex)}${ex.audioCaption?`<div class="notice">${esc(ex.audioCaption)}</div>`:''}${ex.code?`<pre><code>${esc(ex.code)}</code></pre><p class="caption">Read this here; follow this lesson’s instructions when trying it in <a href="https://strudel.cc/" target="_blank" rel="noopener">external Strudel ↗</a>. This app does not execute Strudel code.</p>`:''}${ex.chords?`<div class="chord-sequence">${ex.chords.map((ns,i)=>`<div class="note-tile"><small>Chord ${i+1}</small>${ns.map(noteName).join(' · ')}</div>`).join('')}</div><div class="audio-controls"><button id="playChords">${ex.compareChords?'Play chord sequence A':'Play chord sequence'}</button><button class="stopSound">Stop</button></div><p class="caption">A simplified listening model: equal 0.9-second chord spacing, quiet synthesized tone. Listen for harmonic movement, not a full arrangement.</p>`:''}${ex.notes?`<div class="note-strip" aria-label="Notes in the example">${ex.notes.map((n,i)=>`<span class="note-tile">${esc(ex.noteNames?.[i]||noteName(n))}<small>MIDI ${n}</small></span>`).join('')}</div><div class="audio-controls"><button id="playNotes">Play notes in order</button><button id="playChord">${ex.chord?'Play written chord':'Play together'}</button><button class="stopSound">Stop</button></div><p class="caption">${ex.chord?'Together plays the written chord; in order lets you inspect each pitch.':'Same pitches, two listening views. Together is a chord preview—not a performance of the written example.'} Octave labels here use middle C = C4 / MIDI 60; DAW octave labels can differ. Unless the lesson supplies a spelling, black-key labels use sharps (for example A♯ is the same piano key as B♭).</p>`:''}${ex.beats?`<div class="rhythm-timeline" style="--steps:${(ex.beatsPerBar||4)*(ex.barCount||1)*4}" role="img" aria-label="Hit onset positions in beats from zero: ${esc(ex.beats.join(', '))}">${ex.beats.map(b=>`<span class="rhythm-hit" style="left:${b/((ex.beatsPerBar||4)*(ex.barCount||1))*100}%" title="${b} beats after start"></span>`).join('')}</div><p class="caption">${ex.barCount||1} bar(s), ${ex.beatsPerBar||4} beats each. Lines mark quarter-beat subdivisions; dark marks show exact hit onsets, including off-grid timing. Positions from the start (in beats): ${esc(ex.beats.join(', '))}. This is a fixed timing diagram, not a moving playhead.</p><label for="tempo">Listening tempo: <output id="tempoValue">${ex.bpm||100}</output> BPM</label><input id="tempo" type="range" min="50" max="180" value="${ex.bpm||100}"><div class="audio-controls"><button id="playBeats">${(ex.barCount||1)===1?'Play one bar':'Play '+ex.barCount+' bars'}</button><button class="stopSound">Stop</button></div>`:''}${ex.compareNotes||ex.compareBeats||ex.compareChords?`<div class="model-note"><h3>Compare a changed case</h3><p>${esc(ex.compareText||'Listen to the second case, then explain what changed.')}</p>${ex.compareNotes?`<div class="note-strip">${ex.compareNotes.map(n=>`<span class="note-tile">${noteName(n)}</span>`).join('')}</div>`:''}<button id="playCompare">Play comparison</button></div>`:''}${ex.notes||ex.beats||ex.chords?'<p class="audio-status" role="status">Quiet synthesized demo, capped at 12 seconds. Start with low device volume; no autoplay.</p>':''}</section>`}
function lesson(id){const l=all.find(l=>l.id===id);if(!l){$('#main').innerHTML='<h1>Lesson not found</h1><a href="#home">Return to the studio</a>';return}track=l.track;nav();const list=courses[track],idx=list.indexOf(l),pr=l.prerequisites.map(id=>all.find(x=>x.id===id)).filter(Boolean);$('#main').innerHTML=`<div class="breadcrumb"><a href="#map/${track}">${titles[track]}</a><span>/</span>${l.genre&&l.genre!=='bridge'?`<a href="#genre/${l.genre}">${esc(l.unit)}</a>`:esc(l.unit)}</div><div class="lesson-heading"><div><span class="pill">${esc(l.level)}</span><h1>${esc(l.title)}</h1></div><span class="lesson-count">${idx+1} / ${list.length}</span></div>${pr.length?`<div class="prereq">Builds on: ${pr.map(p=>`<a href="#lesson/${p.id}">${esc(p.title)}</a>${passed.has(p.id)?' ✓':''}`).join(' · ')}. You can review these first; nothing is locked.</div>`:'<p class="lesson-preparation">Start here. No prior knowledge needed.</p>'}<div class="steps" role="group" aria-label="Lesson sections">${['Understand','See & hear','Try it'].map((s,i)=>`<button class="step ${step===i?'active':''}" data-step="${i}" aria-pressed="${step===i}"><span>0${i+1}</span>${s}</button>`).join('')}</div>${step===0?`<div class="lesson-grid"><article class="reading"><p class="goal"><strong>${esc(l.goal)}</strong></p>${l.explain.map(p=>`<p>${esc(p)}</p>`).join('')}</article>${example(l)}</div>`:step===1?`${example(l)}<div class="notice">Before replaying or reading again: predict what will happen. Then explain one thing you noticed in your own words.</div>`:`<section class="reading"><div class="eyebrow">CHECK YOUR UNDERSTANDING</div><h2>${esc(l.practice.question)}</h2><p class="check-explainer">Choose an answer to see the reasoning. You can retry without losing progress.</p>${l.practice.options.map((o,i)=>`<button class="choice" data-choice="${i}">${esc(o)}</button>`).join('')}<div id="feedback" class="feedback" role="status"></div><section class="model-note"><h3>Make the idea yours</h3><p>${esc(l.tryIt)}</p></section></section>`}<section class="lesson-glossary"><div class="eyebrow">WORDS IN THIS LESSON</div><dl>${l.terms.map(t=>`<div><dt>${esc(t)}</dt><dd>${esc(l.glossary[t])}</dd></div>`).join('')}</dl></section><footer class="lesson-footer"><div>${idx?`<a href="#lesson/${list[idx-1].id}">← Previous idea</a>`:'<a href="#map/'+track+'">Course map</a>'}</div><div class="audio-controls"><button id="markDone" ${!passed.has(l.id)?'disabled':''}>${completed.has(l.id)?'✓ Reflected on':'Mark reflected on'}</button>${step<2?'<button id="nextStep" class="primary">'+(step===0?'Explore the example':'Check understanding')+' →</button>':idx<list.length-1?`<a class="link-button primary" href="#lesson/${list[idx+1].id}">Next idea →</a>`:`<a class="link-button primary" href="#map/${track}">Review your path →</a>`}</div></footer><p class="caption">“Reflected on” becomes available after a correct check. It records your reflection, not certified mastery.</p>${l.sources?.length?`<div class="secondary-nav">${l.sources.map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener">Source documentation ${i+1} ↗</a>`).join('')}</div>`:''}`;
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{stop();step=+b.dataset.step;lesson(id);$('#main').focus({preventScroll:true})});$('#nextStep')?.addEventListener('click',()=>{stop();step++;lesson(id);$('#main').focus()});document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=async()=>{const i=+b.dataset.choice,ok=i===l.practice.answer;const explanation=l.practice.feedback[i];$('#feedback').textContent=(/^(yes|correct|not quite|no[, .])/i.test(explanation)?'':ok?'Yes. ':'Not quite. ')+explanation;$('#feedback').classList.toggle('wrong',!ok);document.querySelectorAll('[data-choice]').forEach(x=>x.classList.remove('selected','correct','wrong'));b.classList.add(ok?'correct':'wrong');if(ok){await progressStore.pass(id);if(location.hash==='#lesson/'+id&&$('#markDone'))$('#markDone').disabled=!passed.has(id)}});$('#markDone').onclick=async()=>{await progressStore.complete(id)};const status=$('.audio-status');$('#playChords')?.addEventListener('click',()=>play({chords:l.example.chords},status));$('#playNotes')?.addEventListener('click',()=>play({notes:l.example.notes,wave:l.example.wave||'sine'},status));$('#playChord')?.addEventListener('click',()=>play({notes:l.example.notes,chord:true,wave:l.example.wave||'sine'},status));$('#playBeats')?.addEventListener('click',()=>play({beats:l.example.beats,bpm:+$('#tempo').value,beatsPerBar:l.example.beatsPerBar||4,barCount:l.example.barCount||1},status));$('#playCompare')?.addEventListener('click',()=>play({notes:l.example.compareNotes,chords:l.example.compareChords,beats:l.example.compareBeats,bpm:+($('#tempo')?.value||l.example.bpm||100),chord:!!l.example.compareChord,wave:l.example.compareWave||l.example.wave||'sine'},status));document.querySelectorAll('.stopSound').forEach(b=>b.addEventListener('click',stop));$('#tempo')?.addEventListener('input',()=>{$('#tempoValue').textContent=$('#tempo').value;stop()});}
function refs(){ $('#main').innerHTML='<div class="eyebrow">A COMPANION, NOT A CHECKLIST</div><h1>Strudel function guide</h1><p class="map-intro">Search the broader command families after learning the essentials. Availability depends on Strudel version, packages and output. An alias is another name, not a new skill to memorize.</p><label for="refSearch">Find a name, concept or category</label><input id="refSearch" class="search" type="search" placeholder="Try filter, fast, chord…"><div class="filter-row"><label for="refCategory">Category</label><select id="refCategory"><option value="">All categories</option></select><span id="refCount" class="count" role="status"></span></div><div class="notice">The October 3 snapshot is supplemented by a bounded October 28, 2026 audit of official live source and published packages. Entry notes distinguish source review from pinned-package pure-pattern tests. No current-live audio or full-API completeness claim. Helpers, aliases and optional engines are labeled. <a href="reference-scope.json">Coverage and verification scope →</a></div><div id="refResults" class="ref-list"></div><button id="moreRefs" hidden>Show more results</button>';const cats=[...new Set(reference.map(r=>r.category||'Other'))].sort();$('#refCategory').innerHTML+=cats.map(c=>`<option>${esc(c)}</option>`).join('');$('#refSearch').value=referenceState.q;$('#refCategory').value=referenceState.category;let limit=referenceState.limit;function results(){referenceState.q=$('#refSearch').value;referenceState.category=$('#refCategory').value;referenceState.limit=limit;const q=referenceState.q.toLowerCase().trim(),cat=referenceState.category,rows=searchReferences(reference,q,cat);$('#refCount').textContent=`${rows.length} matching ${rows.length===1?'entry':'entries'}`;$('#refResults').innerHTML=rows.slice(0,limit).map(r=>renderRef(r)).join('');$('#moreRefs').hidden=rows.length<=limit}$('#refSearch').oninput=$('#refCategory').onchange=()=>{limit=30;results()};$('#moreRefs').onclick=()=>{limit+=30;results()};results()}
function renderRef(r){return `<article class="ref-card"><h2>${esc(r.name)}</h2><span class="tag">${esc(r.category)}</span>${r.status?`<span class="tag warn">${esc(r.status)}</span>`:''}<p>${esc(r.description||r.definition||r.summary||'')}</p>${r.syntax?`<p><strong>Syntax / parameter outline</strong></p><pre><code>${esc(r.syntax)}</code></pre>`:''}${r.example?`<p><strong>Example / usage fragment</strong></p><pre><code>${esc(r.example)}</code></pre>`:''}${r.notes?`<p class="caption">${esc(Array.isArray(r.notes)?r.notes.join(' '):r.notes)}</p>`:''}${r.aliases?.length?`<p><small>Aliases: ${esc(r.aliases.join(', '))}</small></p>`:''}<div class="lesson-links">${(r.lessonIds||[]).map(id=>all.find(l=>l.id===id)).filter(Boolean).map(l=>`<a href="#lesson/${l.id}">${esc(l.title)} →</a>`).join('')}${!(r.lessonIds||[]).length?'<a href="#lesson/s31">Background: reading a function reference →</a>':''}${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener">Source / documentation ↗</a>`:''}</div></article>`}
function terms(query=null){ $('#main').innerHTML='<div class="eyebrow">PLAIN WORDS FOR MUSICAL IDEAS</div><h1>Glossary</h1><label for="termSearch">Find a term</label><input class="search" id="termSearch" type="search"><div id="termResults" class="glossary-grid"></div>';$('#termSearch').value=query===null?glossaryQuery:query;const draw=()=>{glossaryQuery=$('#termSearch').value;const q=glossaryQuery.toLowerCase();$('#termResults').innerHTML=Object.entries(glossary).filter(([k,v])=>(k+' '+v).toLowerCase().includes(q)).map(([k,v])=>`<dl class="ref-card"><dt>${esc(k)}</dt><dd>${esc(v)}</dd><dd class="lesson-links">${all.filter(l=>l.terms.some(t=>t.toLowerCase()===k.toLowerCase())).slice(0,4).map(l=>`<a href="#lesson/${l.id}">${esc(l.title)} →</a>`).join('')}</dd></dl>`).join('')||'<p>No matching term. Try a shorter word.</p>'};$('#termSearch').oninput=draw;draw()}
function about(){ $('#main').innerHTML=`<article class="about"><div class="eyebrow">ABOUT THE STUDIO</div><h1>Understand first. Create with intention.</h1><section><h2>Two paths, one practice</h2><p>MusicQuest teaches music theory relevant to DAW production and a separate Strudel coding path. Begin with no music or coding knowledge. The sequence grows toward advanced techniques, with named prerequisites and original examples. This is a bounded course, not an encyclopedia of all musical traditions or a promise of professional results.</p><p>Dubstep, brostep, riddim, synthwave and classical ideas inform the kinds of questions we explore: pulse, harmonic motion, contrast, repetition, tension and form. Artist recordings and compositions are not copied. Synthesis concepts describe sound; mixing and mastering require their own craft and are not presented as music theory.</p><p>DAW transfer: piano-roll note position usually represents pitch and time; note length represents duration. Drum sequencers represent hit positions. Translate the musical idea into your chosen DAW rather than looking for a particular version’s button. See the official <a href="https://www.image-line.com/fl-studio-learning/fl-studio-online-manual/html/pianoroll.htm" target="_blank" rel="noopener">FL Studio Piano roll guide</a> and <a href="https://www.image-line.com/fl-studio-learning/fl-studio-online-manual/html/channelrack.htm" target="_blank" rel="noopener">Channel Rack guide</a>.</p></section><section><h2>Sound & accessibility</h2><p>Audio is optional, quiet, original Web Audio synthesis, triggered only by Play. Stop, page navigation and hiding this tab end playback; demos are bounded. Begin with low device volume. Labeled note and rhythm views remain available without audio. These listening models simplify timbre and performance; they are not a Strudel engine.</p></section><section><h2>Learning & progress</h2><p>Correct checks unlock a voluntary “reflected on” marker, not a mastery certificate. No lesson is locked. Saving is off until you choose it; progress stays in this browser. Export a backup before clearing browser data or changing devices. Import accepts MusicQuest progress only and merges recognized lessons without replacing your existing progress. Open tabs refresh saved progress changes; only one tab should change saving settings at a time. No offline cache or cloud sync is promised. No account, cloud sync or third-party analytics is added by this app.</p></section><section><h2>Sources & scope</h2><p>Lesson explanations and examples are original. Function facts are checked against <a href="https://strudel.cc/workshop/" target="_blank" rel="noopener">official Strudel learning documentation</a> and the versioned <a href="https://github.com/AuroraX98/Strudel-Cheat-Sheet" target="_blank" rel="noopener">AuroraX98 Strudel Cheat Sheet</a>. The broader reference distinguishes command families, aliases, legacy names, developer helpers and optional extensions; it is not a guarantee all names run in a default REPL.</p><p>Code is read here and tried in <a href="https://strudel.cc/" target="_blank" rel="noopener">external Strudel</a>. Its own samples, packages, documentation and licensing apply there. No Strudel runtime or external audio library is embedded here.</p><p>Reference provenance and notices: <a href="sources.json">source record</a>. Course release 1.1.1 · October 2026. <a href="#genres">Genre arrangement workshops</a> add distinct section studies for seven genres. Classical covers selected forms; cinematic follows narrative purpose, not a universal song layout.</p></section></article>`}
function notFound(message){$('#main').innerHTML=`<h1>That link could not be opened.</h1><p>${esc(message)}</p><div class="secondary-nav"><a href="#map/${track}">Return to the course map →</a><a href="#home">Studio home →</a></div>`}
function route(){stop();step=0;const [kind,raw]=location.hash.slice(1).split('/');let arg=raw;try{if(raw!==undefined)arg=decodeURIComponent(raw)}catch{notFound('The link contains an invalid encoded character. Your progress is unchanged.');$('#main').focus({preventScroll:true});return}if(kind==='map'&&courses[arg])track=arg;if(kind==='genres'||kind==='genre')track='theory';if(kind==='unit'){const found=all.find(l=>l.unit===arg);if(found)track=found.track}if(kind==='lesson'){const l=all.find(l=>l.id===arg);if(l)track=l.track}nav();if(kind==='lesson')lesson(arg);else if(kind==='map')map();else if(kind==='unit')map(arg||'');else if(kind==='genres'||kind==='genre')genres(arg||'');else if(kind==='reference')refs();else if(kind==='glossary')terms(arg===undefined?null:arg);else if(kind==='about')about();else home();$('#sidebar').classList.remove('open');$('#navToggle').setAttribute('aria-expanded','false');window.scrollTo(0,0);$('#main').focus({preventScroll:true})}
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus()};$('#navToggle').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#navToggle').setAttribute('aria-expanded',open);if(open)$('#courseSelect').focus();else $('#navToggle').focus()};$('#sidebar').addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('open')){$('#sidebar').classList.remove('open');$('#navToggle').setAttribute('aria-expanded','false');$('#navToggle').focus()}});$('#unitSelect').onchange=()=>{if($('#unitSelect').value)location.hash='unit/'+encodeURIComponent($('#unitSelect').value)};$('#courseSelect').onchange=()=>location.hash='map/'+$('#courseSelect').value;$('#progressButton').onclick=()=>{$('#progressPanel').hidden=!$('#progressPanel').hidden;$('#progressButton').setAttribute('aria-expanded',!$('#progressPanel').hidden)};
$('#saveProgress').onchange=async()=>{if(!ready)return;await progressStore.setEnabled($('#saveProgress').checked)};
$('#exportProgress').onclick=()=>{if(!ready)return;const b=new Blob([JSON.stringify(progressStore.exportData(),null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='musicquest-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
$('#importButton').onclick=()=>{if(ready){importRequest++;$('#importProgress').click()}};$('#importProgress').onchange=async e=>{const request=++importRequest;try{if(!ready)return;const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('File is too large (maximum 100,000 bytes).');const text=await file.text();if(request!==importRequest)return;await progressStore.importText(text)}catch(err){if(request===importRequest)syncProgress(progressStore.snapshot(),'Import failed: '+err.message,false)}finally{e.target.value=''}};
$('#resetProgress').onclick=async()=>{if(ready&&confirm('Clear your MusicQuest checks and reflection markers? This also clears saved MusicQuest progress in other open tabs, but does not affect other apps.')){importRequest++;await progressStore.clear()}};
window.addEventListener('storage',e=>{if(ready&&(e.key===PROGRESS_KEY||e.key===null))progressStore.refreshFromStorage()});
try{const data=await Promise.all(['theory','strudel','reference','glossary'].map(n=>fetch(n+'.json').then(r=>{if(!r.ok)throw Error(n);return r.json()})));courses={theory:data[0],strudel:data[1]};all=Object.entries(courses).flatMap(([t,list])=>list.map(l=>Object.assign(l,{track:t})));reference=data[2];glossary=data[3];const storage={getItem:k=>window.localStorage.getItem(k),setItem:(k,v)=>window.localStorage.setItem(k,v),removeItem:k=>window.localStorage.removeItem(k)};progressStore=createProgressStore({storage,locks:navigator.locks,knownIds:new Set(all.map(l=>l.id)),onChange:syncProgress});progressStore.initialize();ready=true;for(const id of ['saveProgress','exportProgress','importButton','resetProgress','importProgress'])$('#'+id).disabled=false;window.addEventListener('hashchange',route);route()}catch(e){$('#main').innerHTML='<h1>The studio could not load.</h1><p>Please refresh. If this continues, a course data file may be unavailable.</p>';$('#storageMessage').textContent='Lessons did not load; saved progress has not been changed.';console.error(e)}
